const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes,
})

// Atualiza título e favicon após cada navegação
router.afterEach((to: RouteLocationNormalized) => {
  // Suporta tanto 'title' quanto 'titulo' por compatibilidade
  const title = (to.meta && ((to.meta as any).title || (to.meta as any).titulo)) as
    | string
    | undefined
  if (title) {
    document.title = title
  }

  // Se existir meta.icon: pode ser uma string SVG inline (começa com "<svg")
  // ou uma URL (/icons/...) — caso contrário mantém o favicon atual.
  const iconMeta = (to.meta && (to.meta as any).icon) as string | undefined
  if (iconMeta) {
    const link = ensureFaviconLink()
    const icon = String(iconMeta).trim()

    if (icon.startsWith('<svg')) {
      link.href = svgToDataUri(icon)
    } else {
      // aceita URLs relativas ou absolutas
      link.href = icon
    }
  }
})

export default router
